import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import csv,json,numpy as np
from experiment import ROOT
from group_poles import unpack

def read(name):return list(csv.DictReader((ROOT/name).open())) if (ROOT/name).exists() else []
def table(rows,keys,labels):
 lines=['| '+' | '.join(labels)+' |','|'+'|'.join(['---']*len(keys))+'|']
 for r in rows:lines.append('| '+' | '.join(str(r[k]) for k in keys)+' |')
 return '\n'.join(lines)
def main():
 modes=read('mode_summary.csv');poles=read('mode_poles.csv');costs=read('computational_costs.csv');val=json.loads((ROOT/'validation.json').read_text());R=json.loads((ROOT/'responses.json').read_text());env=json.loads((ROOT/'environment.json').read_text());source=json.loads((ROOT/'source_j1.json').read_text());local=json.loads((ROOT/'fresh_local_sum_rules.json').read_text());lines=[]
 lines.append('# 27-spin scalar dimer and chirality dynamics\n')
 lines.append('The priority isotropic chirality and small-finite-Q dimer experiments have independently converged partial poles, complete complex residue matrices, exact direct-H moments, and explicit ground-manifold subtraction. Coupling and K/K′ results included below are completed calculations where listed. Finite block-Krylov quadrature is retained as an approximation to unresolved response, never as a list of verified eigenstates. All weights below use the fixed normalized isotropic reference face modes; isotropic results average the K/K′ orbital ground pair after individual deflation.\n')
 overview=[]
 for r in modes:
  if r['mode']=='chi' and r['response'] not in ['isotropic_G_pair_average','j09_G','j07_G','isotropic_K_pair_average']:continue
  if r['mode']=='D' and r['response'] not in ['isotropic_Q_pair_average','j09_q','isotropic_K_pair_average']:continue
  overview.append({'response':r['response'],'mode':r['mode'],'M0':f"{float(r['M0_positive_energy']):.10f}",'M1':f"{float(r['M1']):.10f}",'M2':f"{float(r['M2']):.10f}",'fraction':f"{100*float(r['resolved_fraction']):.2f}%",'remaining':f"{float(r['unresolved_M0']):.10f}"})
 lines.append(table(overview,['response','mode','M0','M1','M2','fraction','remaining'],['Response','Probe','Exact M0','Exact M1/J','Exact M2/J²','Verified fraction','Unresolved M0'])+'\n')
 for response,kind,title in [('isotropic_G_pair_average','chi','J′/J=1, physical Γ chirality'),('isotropic_Q_pair_average','D','J′/J=1, physical Q=(8/9,7/9) dimer'),('j09_G','chi','J′/J=0.9, same uniform CCW chirality probe'),('j07_G','chi','J′/J=0.7, same uniform CCW chirality probe'),('j09_q','D','J′/J=0.9, finite-Q dimer probe in cell k=(2/3,0)')]:
  ps=sorted([p for p in poles if p['response']==response and p['mode']==kind and float(p['weight'])>1e-8],key=lambda p:float(p['omega']))
  if not ps:continue
  lines.append(title+'. The first appreciable verified lines are:')
  rows=[{'w':f"{float(p['omega']):.10f}",'a':f"{float(p['weight']):.10g}",'r':f"{float(p['H_residual']):.2e}",'s':f"{float(p['S2_residual']):.2e}"} for p in ps[:6]];lines.append(table(rows,['w','a','r','s'],['ω/J','Residue weight','Direct H residual/J','S² residual'])+'\n')
 lines.append('For the isotropic leading Γ chirality mode, the first two poles are at 1.7385684181J and 1.9230101125J. Their weights sum to about 51.2% of its exact M0; the extended search resolves about 69.9% altogether. The exact centroid is 2.700974854J. There is a substantial unresolved higher-energy remainder, so neither these two lines nor the quadrature envelope is a complete spectrum. The orthogonal Γ face mode is retained in every matrix and in the separate face-mode coverage table; its larger missing fraction is not hidden.\n')
 lines.append('For the isotropic leading dimer mode, prominent independently converged lines occur at 0.5142726608J, 0.9488029600J, 0.9823739494J and 1.0211129905J. The exact centroid is 1.385317142J. Several modes, rather than a single isolated-triangle oscillation, carry the response. The full frequency-dependent 6×6 residues distinguish both circular dimer senses and both chirality face fields. At generic Q, finite complex dimer–chirality residues establish that some scalar eigenstates are accessible to both operators. Some cross channels remain forbidden by the little group. At physical Γ the dimer/chirality cross residues vanish within numerical error because their spatial irreducible characters differ. A cross-residue phase depends on the declared operator gauge; magnitudes alone are insufficient, and a nonzero cross residue alone is not a thermodynamic order parameter.\n')
 if 'isotropic_Q_pair_average' in R:
  ps=R['isotropic_Q_pair_average']['poles'];p=min(ps,key=lambda p:p['omega']);z=unpack(p['residue'])[0,4];lines.append(f"For example, the orbital-averaged ω={p['omega']:.10f}J pole has R[D_up,χ_up]={z.real:.10g}{z.imag:+.10g}i in the documented gauge. Its complete matrix is in `complex_residues.csv` and `residues.npz`.\n")
 if 'j09_G' in R:lines.append('At J′/J=0.9 the first uniform-chirality poles shift to 1.6080514946J and 1.7980172286J, with weights 0.1045572484 and 0.0885661428. These frequencies are much larger than the isolated-triangle gap 1−J′/J=0.1. The lattice triangles overlap and interact strongly; the isolated-triangle formula is a calibration, not a prediction for the lattice poles. At J′/J=1 the isolated triangle has no nonzero flavor splitting, while the lattice still has the finite-energy scalar lines reported here.\n')
 lines.append('Physical K/K′ are included as additional diagnostics: direct moment matrices, explicit ground-pair removal, symmetry-derived partner residues, and partial verified poles are supplied. The leading K dimer and chirality modes are only 2.49% and 18.07% resolved, respectively. No full scalar eigenstate enumeration of the primitive-Γ target reached from the K′ source was performed; its lowest reused state is spin-forbidden. Grey K quadrature nodes are not additional converged poles.\n')
 lines.append('All contributing states have S_final=S_ground=1/2. Returned S=3/2 and higher-spin states are deliberately retained as selection-rule tests with negligible scalar overlap. The prior primitive-Γ lowest state at E/J=−14.529841876 has S=3/2 and is not a scalar pole from the isotropic S=1/2 ground state. Low magnetic tower states must not be relabeled as scalar flavor resonances. Coupling comparisons retain cell translations only away from isotropy; the displayed physical-Q form factor is embedded in all six cell faces and is not a primitive-momentum eigenstate label there.\n')
 lines.append('The known zero-energy ground-pair contributions are kept separately. The orthogonal Γ chirality face mode carries 0.01847107147, and a subleading physical-K dimer mode carries orbital-averaged 0.12089426383. The leading Γ chirality and small-Q dimer probes have no such known zero-energy contribution. At physical Γ the zero-energy chirality term is diagonal in a selected physical-K source and changes its mean sign in K′; in the orbital ensemble it is ground-state variance. The physical-K dimer zero term can instead connect the two orbital ground states. Neither is a positive-frequency excitation. Fixed-Sz scalar operators do not access the opposite-M member of the spin doublet. Local circular-dimer sum rules include zero frequency; the positive-energy difference includes the explicit elastic correction. `fresh_local_sum_rules.json` verifies this with freshly evaluated local RDMs and orbital-ground amplitudes, rather than applying a local identity blindly at each Fourier Q.\n')
 lines.append('Input validation reproduces all 32 supplied SHA256 entries and the independent isolated-triangle algebra/spectra. The original isotropic checkpoint had H residual 8.30×10⁻⁹J and S² residual 1.72×10⁻⁸; after a measured refinement these are '+f"{source['H_residual']:.3e}J and {source['spin']['S2_eigen_residual']:.3e}."+' The original is preserved. The supplied 27-spin reference contains numerical M0 targets, but no independent numerical 27-spin M1/M2 reference table. New M1/M2 are direct Hamiltonian-action results, checked against independent tiny-cluster spectral sums and block-Krylov moment reproduction. Matching quadrature moments does not converge its individual nodes.\n')
 lines.append('Validation of the final data gives '+f"maximum exported scalar H residual {val['max_pole_H_residual']:.3e}J, maximum S² residual {val['max_pole_S2_residual']:.3e}, and maximum spin-forbidden weight {val['maximum_forbidden_spin_weight']:.3e}. The smallest residue eigenvalue is {val['residue_min_eigenvalue']:.3e}; the smallest unresolved-moment eigenvalue is {val['remainder_moment_min_eigenvalue']:.3e}, consistent with rounding."+' Full comparisons and per-channel errors are in `validation.json`, `input_validation.json`, and the native/primitive/little-group test records.\n')
 lines.append('Exact degeneracies are treated as eigenspaces: residues use V(V†V)⁻¹V†. The unrestricted complex ARPACK Γ calculation returned nonorthogonal vectors in some exactly degenerate levels; a naive sum would be basis dependent. The recorded Gram matrices correct this explicitly. Compatible symmetry blocks are then merged at the same energy. Sixfold-Q partners are derived by tested exact operator covariance maps and labeled as symmetry-derived, not fresh solves.\n')
 if costs:
  wall=sum(float(x['wall_seconds']) for x in costs if x.get('wall_seconds'));rss=max(float(x['peak_process_RSS_MiB']) for x in costs if x.get('peak_process_RSS_MiB'));hc=sum(int(x['H_calls']) for x in costs if x.get('H_calls'))
  lines.append(f"Instrumented phases total {wall/60:.2f} minutes of summed wall time and {hc} H actions (S² actions are explicitly counted where noted); the largest recorded process RSS is {rss:.1f} MiB. These are measured phase records, not a single elapsed turnaround or whole-machine peak. Independent phases may overlap. Early seed timings stop before checkpoint compression, whereas queue task records include that overhead; subsequent seed records state their scope. CPU seconds are reported only where instrumented. Hardware: {env['CPU_model']}, two-core quota, 8 GiB cap, OpenMP=2, BLAS=1. Arnoldi H-action counts are the recorded iteration measure; restart-cycle counts are not exposed by SciPy.\n")
 if (ROOT/'finite_solver_restart.json').exists():lines.append('One unrestricted finite-cell startup was terminated without accepting any Ritz values, then replaced successfully by the two exact compatible reflection blocks. The queue records preserve that termination; final poles come from the successful replacements. The parent task wall includes the replacement interval and is not added again to per-block solve walls. `finite_solver_restart.json` and `abandoned_solver_resources.json` document the accounting.\n')
 lines.append('The limiting resource for complete spectral resolution is the cost of resolving many higher eigenstates in sectors with up to 2,228,700 complex basis coefficients under the two-CPU/eight-GiB allocation. Bounded target searches and Krylov bases fit, but the unresolved spectrum has not been independently diagonalized. Remaining matrix moments are saved explicitly. For any normalized probe and cutoff Ω>0, unidentified weight above Ω is bounded by min(R0,R1/Ω,R2/Ω²), and weight below Ω is at least R0 minus that bound. `remaining_weight_bounds.csv` evaluates these positive-measure bounds; they are floating-point moment bounds, not certified interval arithmetic. No unresolved Ritz value is called a converged eigenvalue.\n')
 lines.append('These calculations establish genuine finite-frequency scalar matrix elements and dimer–chirality co-accessibility on this finite cluster. They go beyond static doublet probabilities, while not proving coherent thermodynamic resonance or order. The supplied physical-120-degree magnetic benchmark S(K)=2.9489820736 is a different SU(2) tensor channel. Coexisting magnetic correlations and scalar peaks do not identify a chiral phase, valence-bond order, a thermodynamic transition, or a linewidth. All figures use unbroadened discrete weights; grey quadrature nodes are approximations. No physical damping or magnon lifetime is extracted.\n')
 (ROOT/'report.md').write_text('\n\n'.join(lines));print('Report generated.')
if __name__=='__main__':main()
